const RNG_B=[['Short',0],['Medium',-2],['Long',-4],['Extreme',-8]],RNG_C=[['No cover',0],['Light cover',-1],['Medium cover',-2],['Heavy cover',-4],['Near-total cover',-6]],RNG_L=[['Bright light',0],['Dim light',-2],['Dark',-4],['Pitch black',-6]];
